#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define VL 16
#elif defined(__AVX__)
#define VL 8
#else
#define VL 4
#endif

#define MR 6
#define NR (2 * VL)
#define KC 256
#define MCP 20            /* row block = MCP * MR = 120 rows */
#define JCOLS 64
#define JCP ((JCOLS / NR) > 0 ? (JCOLS / NR) : 1)

typedef float vf __attribute__((vector_size(VL * 4)));

static inline vf vload(const float *p) { vf v; memcpy(&v, p, sizeof v); return v; }
static inline void vstore(float *p, vf v) { memcpy(p, &v, sizeof v); }

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first, int mr, int nr)
{
    vf z = {0};
    vf c00 = z, c01 = z, c10 = z, c11 = z, c20 = z, c21 = z;
    vf c30 = z, c31 = z, c40 = z, c41 = z, c50 = z, c51 = z;

    for (int p = 0; p < kc; p++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ROW(r, x0, x1) do { float *cr = c + (size_t)(r) * ldc;            \
        if (first) { vstore(cr, x0); vstore(cr + VL, x1); }                 \
        else { vstore(cr, vload(cr) + x0); vstore(cr + VL, vload(cr + VL) + x1); } } while (0)
        ROW(0, c00, c01); ROW(1, c10, c11); ROW(2, c20, c21);
        ROW(3, c30, c31); ROW(4, c40, c41); ROW(5, c50, c51);
#undef ROW
    } else {
        float t[MR][NR] __attribute__((aligned(64)));
        vstore(&t[0][0], c00); vstore(&t[0][VL], c01);
        vstore(&t[1][0], c10); vstore(&t[1][VL], c11);
        vstore(&t[2][0], c20); vstore(&t[2][VL], c21);
        vstore(&t[3][0], c30); vstore(&t[3][VL], c31);
        vstore(&t[4][0], c40); vstore(&t[4][VL], c41);
        vstore(&t[5][0], c50); vstore(&t[5][VL], c51);
        for (int i = 0; i < mr; i++) {
            float *cr = c + (size_t)i * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = t[i][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += t[i][j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int nbp = (n + NR - 1) / NR;   /* B panels */
    int nap = (n + MR - 1) / MR;   /* A panels */
    size_t bsz = ((size_t)KC * nbp * NR * sizeof(float) + 63) & ~(size_t)63;
    size_t asz = ((size_t)KC * nap * MR * sizeof(float) + 63) & ~(size_t)63;
    float *Bp = (float *)aligned_alloc(64, bsz);
    float *Ap = (float *)aligned_alloc(64, asz);

    int nib = (nap + MCP - 1) / MCP;
    int njb = (nbp + JCP - 1) / JCP;

    #pragma omp parallel
    {
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);

            /* cooperative packing of both B and A panels */
            #pragma omp for schedule(dynamic, 4)
            for (int t = 0; t < nbp + nap; t++) {
                if (t < nbp) {
                    int j0 = t * NR;
                    float *dst = Bp + (size_t)t * kc * NR;
                    if (j0 + NR <= n) {
                        for (int p = 0; p < kc; p++)
                            memcpy(dst + (size_t)p * NR, B + (size_t)(pc + p) * n + j0,
                                   NR * sizeof(float));
                    } else {
                        int w = n - j0;
                        for (int p = 0; p < kc; p++) {
                            const float *src = B + (size_t)(pc + p) * n + j0;
                            float *d = dst + (size_t)p * NR;
                            int jj = 0;
                            for (; jj < w; jj++) d[jj] = src[jj];
                            for (; jj < NR; jj++) d[jj] = 0.0f;
                        }
                    }
                } else {
                    int ip = t - nbp;
                    int i0 = ip * MR;
                    float *dst = Ap + (size_t)ip * kc * MR;
                    for (int ii = 0; ii < MR; ii++) {
                        int row = i0 + ii;
                        if (row < n) {
                            const float *src = A + (size_t)row * n + pc;
                            for (int p = 0; p < kc; p++) dst[(size_t)p * MR + ii] = src[p];
                        } else {
                            for (int p = 0; p < kc; p++) dst[(size_t)p * MR + ii] = 0.0f;
                        }
                    }
                }
            }

            /* fine-grained dynamic compute tasks */
            #pragma omp for collapse(2) schedule(dynamic, 1)
            for (int ib = 0; ib < nib; ib++) {
                for (int jb = 0; jb < njb; jb++) {
                    int ip0 = ib * MCP, ip1 = ip0 + MCP < nap ? ip0 + MCP : nap;
                    int jp0 = jb * JCP, jp1 = jp0 + JCP < nbp ? jp0 + JCP : nbp;
                    for (int jp = jp0; jp < jp1; jp++) {
                        int j0 = jp * NR;
                        int nr = n - j0 < NR ? n - j0 : NR;
                        const float *bp = Bp + (size_t)jp * kc * NR;
                        for (int ip = ip0; ip < ip1; ip++) {
                            int i0 = ip * MR;
                            int mr = n - i0 < MR ? n - i0 : MR;
                            kernel(kc, Ap + (size_t)ip * kc * MR, bp,
                                   C + (size_t)i0 * n + j0, n, first, mr, nr);
                        }
                    }
                }
            }
        }
    }

    free(Bp);
    free(Ap);
}
